      --teal-mid: #b3dde0;
      --charcoal: #231F20;
      --charcoal-light: #4a4546;
      --coral: #E85D38;
      --coral-hover: #d04e2b;
      --amber: #F0942A;
      --white: #ffffff;
      --off-white: #f8fafb;
      --gray-50: #f4f6f7;
      --gray-100: #eaedee;
      --gray-200: #d4dadc;
      --gray-400: #8e9fa3;
      --gray-500: #6b7c80;
      --gray-700: #374649;
      --font-display: 'Plus Jakarta Sans', sans-serif;
      --font-body: 'DM Sans', sans-serif;
      --shadow-sm: 0 1px 3px rgba(35,31,32,0.08), 0 1px 2px rgba(35,31,32,0.04);
      --shadow-md: 0 4px 12px rgba(35,31,32,0.10), 0 2px 6px rgba(35,31,32,0.06);
      --shadow-lg: 0 10px 30px rgba(35,31,32,0.12), 0 4px 12px rgba(35,31,32,0.08);
      --radius-sm: 6px;
      --radius-md: 12px;
      --radius-lg: 20px;
      --radius-xl: 28px;
      --max-width: 1280px;
      --header-h: 64px;
    }

    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font-body);
      color: var(--charcoal);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { cursor: pointer; border: none; background: none; font-family: inherit; }
    input { font-family: inherit; }
    ul { list-style: none; }

    .container {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 24px;
    }

    /* =============================================
       HEADER & NAVIGATION
    ============================================= */
    .site-header {
      position: sticky;
      top: 0;
      z-index: 1000;
      background: var(--white);
      border-bottom: 1px solid var(--gray-100);
      box-shadow: var(--shadow-sm);
    }

    .header-inner {
      display: flex;
      align-items: center;
      height: var(--header-h);
      gap: 32px;
    }

    .site-logo {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-shrink: 0;
      text-decoration: none;
    }

    .logo-mark {
      width: 36px;
      height: 36px;
      background: var(--teal);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-mark svg { width: 20px; height: 20px; }

    .logo-text {
      font-family: var(--font-display);
      font-size: 22px;
      font-weight: 800;
      color: var(--charcoal);
      letter-spacing: -0.4px;
    }

    .logo-text span { color: var(--teal); }

    .main-nav {
      flex: 1;
      display: flex;
      align-items: center;
    }

    .nav-list {
      display: flex;
      align-items: center;
      gap: 2px;
      list-style: none;
    }

    .nav-item {
      position: relative;
    }

    .nav-btn {
      display: flex;
      align-items: center;
      gap: 5px;
      padding: 8px 14px;
      font-family: var(--font-display);
      font-size: 14px;
      font-weight: 600;
      color: var(--charcoal);
      border-radius: var(--radius-sm);
      transition: background 0.15s, color 0.15s;
      white-space: nowrap;
    }

    .nav-btn:hover,
    .nav-item.open .nav-btn {
      background: var(--teal-light);
      color: var(--teal);
    }

    .nav-btn svg {
      width: 14px;
      height: 14px;
      transition: transform 0.2s;
      opacity: 0.6;
    }

    .nav-item.open .nav-btn svg {
      transform: rotate(180deg);
      opacity: 1;
    }

    /* Mega Menu */
    .mega-menu {
      position: absolute;
      top: calc(100% + 8px);
      left: 0;
      background: var(--white);
      border: 1px solid var(--gray-100);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-lg);
      min-width: 260px;
      padding: 20px;
      opacity: 0;
      visibility: hidden;
      transform: translateY(-8px);
      transition: opacity 0.2s, transform 0.2s, visibility 0.2s;
      z-index: 100;
    }

    .nav-item.open .mega-menu {
      opacity: 1;
      visibility: visible;
      transform: translateY(0);
    }

    .mega-menu-wide {
      min-width: 560px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 8px 24px;
    }

    .mega-menu-section {
      margin-bottom: 12px;
    }

    .mega-menu-heading {
      font-family: var(--font-display);
      font-size: 10px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: var(--teal);
      margin-bottom: 8px;
      padding-bottom: 4px;
      border-bottom: 1px solid var(--teal-light);
    }

    .mega-menu a {
      display: block;
      padding: 5px 8px;
      font-size: 13.5px;
      font-weight: 500;
      color: var(--charcoal-light);
      border-radius: 4px;
      transition: background 0.12s, color 0.12s;
    }

    .mega-menu a:hover {
      background: var(--teal-light);
      color: var(--teal);
    }

    .mega-menu-featured {
      background: var(--teal-light);
      border-radius: var(--radius-sm);
      padding: 12px;
      margin-top: 8px;
    }

    .mega-menu-featured-label {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      color: var(--teal);
      margin-bottom: 4px;
    }

    .mega-menu-featured a {
      font-family: var(--font-display);
      font-size: 13px;
      font-weight: 600;
      color: var(--charcoal);
      padding: 4px 0;
    }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-shrink: 0;
    }

    .btn-subscribe {
      padding: 8px 18px;
      background: var(--coral);
      color: var(--white);
      font-family: var(--font-display);
      font-size: 13px;
      font-weight: 700;
      border-radius: 100px;
      transition: background 0.15s, transform 0.1s;
    }

    .btn-subscribe:hover {
      background: var(--coral-hover);
      transform: translateY(-1px);
    }

    .btn-signin {
      padding: 8px 16px;
      font-family: var(--font-display);
      font-size: 13px;
      font-weight: 600;
      color: var(--teal);
      border: 1.5px solid var(--teal);
      border-radius: 100px;
      transition: background 0.15s, color 0.15s;
    }

    .btn-signin:hover {
      background: var(--teal);
      color: var(--white);
    }

    /* Mobile hamburger */
    .mobile-menu-btn {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: 8px;
      border-radius: 6px;
    }

    .mobile-menu-btn span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--charcoal);
      border-radius: 2px;
      transition: transform 0.2s;
    }

    /* =============================================
       CREDIBILITY TICKER
    ============================================= */
    .credibility-bar {
      background: var(--teal);
      overflow: hidden;
      position: relative;
    }

    .ticker-track {
      display: flex;
      white-space: nowrap;
      animation: ticker-scroll 30s linear infinite;
    }

    .ticker-track:hover {
      animation-play-state: paused;
    }

    @keyframes ticker-scroll {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    .ticker-item {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 10px 40px;
      color: var(--white);
      font-family: var(--font-display);
      font-size: 13px;
      font-weight: 600;
    }

    .ticker-item .ticker-dot {
      width: 5px;
      height: 5px;
      border-radius: 50%;
      background: rgba(255,255,255,0.4);
    }

    .ticker-item .ticker-num {
      color: #7de8ef;
      font-weight: 800;
      font-size: 14px;
    }

    .ticker-item .ticker-icon {
      font-size: 16px;
    }

    /* =============================================
       HERO SECTION
    ============================================= */
    .hero-section {
      background: var(--off-white);
      padding: 48px 0 0;
      border-bottom: 1px solid var(--gray-100);
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1fr 340px;
      gap: 40px;
      align-items: start;
    }

    .hero-content {
      padding-bottom: 48px;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 5px 12px;
      background: var(--teal-light);
      border: 1px solid var(--teal-mid);
      color: var(--teal);
      font-family: var(--font-display);
      font-size: 12px;
      font-weight: 700;
      border-radius: 100px;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      margin-bottom: 20px;
    }

    .hero-badge::before {
      content: '';
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: var(--teal);
    }

    .hero-title {
      font-family: var(--font-display);
      font-size: clamp(32px, 4vw, 52px);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -1.2px;
      color: var(--charcoal);
      margin-bottom: 18px;
      max-width: 640px;
    }

    .hero-subtitle {
      font-size: 16px;
      line-height: 1.65;
      color: var(--gray-500);
      max-width: 520px;
      margin-bottom: 28px;
    }

    .hero-cta-group {
      display: flex;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 13px 26px;
      background: var(--teal);
      color: var(--white);
      font-family: var(--font-display);
      font-size: 14px;
      font-weight: 700;
      border-radius: 100px;
      transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
      box-shadow: 0 4px 14px rgba(2,131,141,0.3);
    }

    .btn-primary:hover {
      background: var(--teal-dark);
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(2,131,141,0.4);
    }

    .btn-text-link {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-family: var(--font-display);
      font-size: 14px;
      font-weight: 600;
      color: var(--teal);
      transition: gap 0.15s;
    }

    .btn-text-link:hover { gap: 10px; }

    .btn-text-link svg { width: 14px; height: 14px; }

    /* Hero challenge badge */
    .hero-visual {
      position: relative;
      align-self: end;
    }

    .challenge-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 28px;
      box-shadow: var(--shadow-lg);
      border: 1px solid var(--gray-100);
      position: relative;
      overflow: hidden;
    }

    .challenge-card::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 4px;
      background: linear-gradient(90deg, var(--teal) 0%, var(--teal-mid) 100%);
    }

    .challenge-badge-visual {
      width: 72px;
      height: 72px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--teal) 0%, #04a0ac 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 16px;
      box-shadow: 0 8px 24px rgba(2,131,141,0.25);
    }

    .challenge-badge-visual svg {
      width: 32px;
      height: 32px;
      color: white;
    }

    .challenge-label {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: var(--teal);
      margin-bottom: 6px;
    }

    .challenge-title {
      font-family: var(--font-display);
      font-size: 18px;
      font-weight: 800;
      color: var(--charcoal);
      margin-bottom: 10px;
      line-height: 1.3;
    }

    .challenge-progress {
      margin-top: 16px;
    }

    .progress-label {
      display: flex;
      justify-content: space-between;
      font-size: 12px;
      font-weight: 600;
      color: var(--gray-500);
      margin-bottom: 8px;
    }

    .progress-bar {
      height: 6px;
      background: var(--gray-100);
      border-radius: 100px;
      overflow: hidden;
    }

    .progress-fill {
      height: 100%;
      background: linear-gradient(90deg, var(--teal), #04b5c4);
      border-radius: 100px;
      width: 40%;
      animation: progress-grow 1.5s ease-out 0.5s both;
    }

    @keyframes progress-grow {
      from { width: 0; }
      to { width: 40%; }
    }

    .challenge-stats {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
      margin-top: 16px;
    }

    .challenge-stat {
      background: var(--gray-50);
      border-radius: var(--radius-sm);
      padding: 10px 12px;
      text-align: center;
    }

    .challenge-stat-num {
      font-family: var(--font-display);
      font-size: 20px;
      font-weight: 800;
      color: var(--teal);
    }

    .challenge-stat-label {
      font-size: 11px;
      color: var(--gray-500);
      margin-top: 2px;
    }

    /* =============================================
       TRENDING
    ============================================= */
    .trending-strip {
      padding: 20px 0;
      border-bottom: 1px solid var(--gray-100);
      background: var(--white);
    }

    .trending-inner {
      display: flex;
      align-items: flex-start;
      gap: 0;
    }

    .trending-label {
      display: flex;
      align-items: center;
      gap: 6px;
      flex-shrink: 0;
      padding-right: 20px;
      border-right: 1px solid var(--gray-200);
      margin-right: 20px;
    }

    .trending-label-text {
      font-family: var(--font-display);
      font-size: 12px;
      font-weight: 800;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: var(--coral);
      white-space: nowrap;
    }

    .trending-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: var(--coral);
      animation: pulse 2s infinite;
    }

    @keyframes pulse {
      0%, 100% { opacity: 1; transform: scale(1); }
      50% { opacity: 0.6; transform: scale(1.3); }
    }

    .trending-articles {
      display: flex;
      flex-wrap: wrap;
      gap: 0;
      flex: 1;
      overflow: hidden;
    }

    .trending-article {
      display: flex;
      align-items: flex-start;
      gap: 8px;
      padding: 2px 16px 2px 0;
      border-right: 1px solid var(--gray-100);
      margin-right: 16px;
    }

    .trending-article:last-child {
      border-right: none;
      padding-right: 0;
      margin-right: 0;
    }

    .trending-article-category {
      flex-shrink: 0;
      font-size: 10px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      color: var(--teal);
      padding: 2px 7px;
      background: var(--teal-light);
      border-radius: 100px;
      white-space: nowrap;
      margin-top: 1px;
    }

    .trending-article a {
      font-size: 13px;
      font-weight: 600;
      color: var(--charcoal);
      line-height: 1.4;
      transition: color 0.15s;
    }

    .trending-article a:hover { color: var(--teal); }

    /* =============================================
       NEWSLETTER CTA (Mid-page)
    ============================================= */
    .newsletter-cta {
      background: linear-gradient(135deg, #012e32 0%, var(--teal-dark) 40%, #024850 100%);
      padding: 56px 0;
      position: relative;
      overflow: hidden;
    }

    .newsletter-cta::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Ccircle cx='30' cy='30' r='2'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E") repeat;
      pointer-events: none;
    }

    .newsletter-cta::after {
      content: '';
      position: absolute;
      right: -100px;
      top: -80px;
      width: 400px;
      height: 400px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(2,180,190,0.15) 0%, transparent 70%);
      pointer-events: none;
    }

    .newsletter-inner {
      position: relative;
      text-align: center;
      max-width: 580px;
      margin: 0 auto;
    }

    .newsletter-eyebrow {
      font-family: var(--font-display);
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1.2px;
      color: #7de8ef;
      margin-bottom: 12px;
    }

    .newsletter-title {
      font-family: var(--font-display);
      font-size: clamp(26px, 3vw, 36px);
      font-weight: 800;
      color: var(--white);
      letter-spacing: -0.6px;
      margin-bottom: 14px;
      line-height: 1.2;
    }

    .newsletter-body {
      font-size: 15px;
      color: rgba(255,255,255,0.72);
      line-height: 1.6;
      margin-bottom: 32px;
    }

    .newsletter-form {
      display: flex;
      gap: 10px;
      max-width: 460px;
      margin: 0 auto 12px;
    }

    .newsletter-input {
      flex: 1;
      padding: 13px 18px;
      background: rgba(255,255,255,0.12);
      border: 1.5px solid rgba(255,255,255,0.25);
      border-radius: 100px;
      color: var(--white);
      font-size: 14px;
      outline: none;
      transition: border-color 0.15s, background 0.15s;
    }

    .newsletter-input::placeholder { color: rgba(255,255,255,0.45); }

    .newsletter-input:focus {
      border-color: rgba(255,255,255,0.6);
      background: rgba(255,255,255,0.18);
    }

    .btn-newsletter {
      padding: 13px 24px;
      background: var(--coral);
      color: var(--white);
      font-family: var(--font-display);
      font-size: 14px;
      font-weight: 700;
      border-radius: 100px;
      white-space: nowrap;
      transition: background 0.15s, transform 0.1s;
    }

    .btn-newsletter:hover {
      background: var(--coral-hover);
      transform: translateY(-1px);
    }

    .newsletter-privacy {
      font-size: 12px;
      color: rgba(255,255,255,0.45);
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 5px;
    }

    /* =============================================
       HEALTH TOPICS CAROUSEL
    ============================================= */
    .section-padding { padding: 64px 0; }

    .section-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 32px;
    }

    .section-eyebrow {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--teal);
      margin-bottom: 6px;
    }

    .section-title {
      font-family: var(--font-display);
      font-size: clamp(22px, 2.5vw, 30px);
      font-weight: 800;
      color: var(--charcoal);
      letter-spacing: -0.5px;
    }

    .link-view-all {
      display: flex;
      align-items: center;
      gap: 5px;
      font-family: var(--font-display);
      font-size: 13px;
      font-weight: 700;
      color: var(--teal);
      white-space: nowrap;
      transition: gap 0.15s;
    }

    .link-view-all:hover { gap: 8px; }
    .link-view-all svg { width: 13px; height: 13px; }

    .carousel-wrapper {
      position: relative;
    }

    .carousel-track {
      display: flex;
      gap: 20px;
      overflow: hidden;
      scroll-behavior: smooth;
    }

    .topic-card {
      flex-shrink: 0;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 12px;
      cursor: pointer;
      width: calc((100% - 80px) / 5);
      min-width: 140px;
    }

    .topic-img-wrap {
      width: 120px;
      height: 120px;
      border-radius: 50%;
      overflow: hidden;
      border: 3px solid var(--white);
      box-shadow: var(--shadow-md);
      transition: transform 0.2s, box-shadow 0.2s;
      background: linear-gradient(135deg, var(--teal-light), var(--teal-mid));
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 40px;
    }

    .topic-card:hover .topic-img-wrap {
      transform: scale(1.06);
      box-shadow: 0 8px 24px rgba(2,131,141,0.2);
      border-color: var(--teal-mid);
    }

    .topic-name {
      font-family: var(--font-display);
      font-size: 13px;
      font-weight: 700;
      color: var(--charcoal);
      text-align: center;
      line-height: 1.3;
    }

    .carousel-arrows {
      display: flex;
      gap: 8px;
      align-items: center;
    }

    .carousel-btn {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: var(--white);
      border: 1.5px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: border-color 0.15s, background 0.15s, transform 0.1s;
      color: var(--charcoal);
    }

    .carousel-btn:hover {
      border-color: var(--teal);
      background: var(--teal-light);
      color: var(--teal);
      transform: scale(1.05);
    }

    .carousel-btn svg { width: 16px; height: 16px; }

    /* =============================================
       HEALTH TOOLS
    ============================================= */
    .tools-section {
      background: var(--off-white);
      padding: 64px 0;
      border-top: 1px solid var(--gray-100);
      border-bottom: 1px solid var(--gray-100);
    }

    .tools-grid {
      display: grid;
      grid-template-columns: 380px 1fr;
      gap: 48px;
      align-items: start;
    }

    .nutrition-hub-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-md);
      border: 1px solid var(--gray-100);
    }

    .nutrition-hub-header {
      background: linear-gradient(135deg, var(--teal) 0%, #04a8b4 100%);
      padding: 28px 28px 24px;
      position: relative;
      overflow: hidden;
    }

    .nutrition-hub-header::after {
      content: '🥗';
      position: absolute;
      right: 20px;
      bottom: -8px;
      font-size: 60px;
      opacity: 0.3;
    }

    .nutrition-hub-eyebrow {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: rgba(255,255,255,0.7);
      margin-bottom: 6px;
    }

    .nutrition-hub-title {
      font-family: var(--font-display);
      font-size: 22px;
      font-weight: 800;
      color: var(--white);
      margin-bottom: 10px;
      line-height: 1.25;
    }

    .nutrition-hub-desc {
      font-size: 13.5px;
      color: rgba(255,255,255,0.8);
      line-height: 1.55;
    }

    .nutrition-hub-cta {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      margin-top: 16px;
      padding: 9px 18px;
      background: rgba(255,255,255,0.2);
      border: 1.5px solid rgba(255,255,255,0.4);
      color: var(--white);
      font-family: var(--font-display);
      font-size: 13px;
      font-weight: 700;
      border-radius: 100px;
      transition: background 0.15s;
    }

    .nutrition-hub-cta:hover { background: rgba(255,255,255,0.32); }

    .nutrition-hub-tools {
      padding: 16px 28px 20px;
      display: flex;
      flex-direction: column;
      gap: 1px;
      background: var(--gray-100);
    }

    .nutrition-tool-item {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 14px 16px;
      background: var(--white);
      border-radius: var(--radius-sm);
      transition: background 0.15s;
      cursor: pointer;
    }

    .nutrition-tool-item:hover { background: var(--teal-light); }

    .nutrition-tool-icon {
      width: 36px;
      height: 36px;
      border-radius: 8px;
      background: var(--teal-light);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      flex-shrink: 0;
    }

    .nutrition-tool-name {
      font-family: var(--font-display);
      font-size: 13px;
      font-weight: 700;
      color: var(--charcoal);
    }

    .nutrition-tool-desc {
      font-size: 12px;
      color: var(--gray-400);
      margin-top: 1px;
    }

    .nutrition-tool-arrow {
      margin-left: auto;
      color: var(--gray-400);
      flex-shrink: 0;
    }

    .nutrition-tool-arrow svg { width: 14px; height: 14px; }

    /* Drug/Care tools */
    .care-tools-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px;
    }

    .care-tool-card {
      background: var(--white);
      border: 1px solid var(--gray-100);
      border-radius: var(--radius-md);
      padding: 20px;
      display: flex;
      flex-direction: column;
      gap: 10px;
      transition: box-shadow 0.2s, border-color 0.2s, transform 0.15s;
      cursor: pointer;
    }

    .care-tool-card:hover {
      box-shadow: var(--shadow-md);
      border-color: var(--teal-mid);
      transform: translateY(-2px);
    }

    .care-tool-icon {
      width: 44px;
      height: 44px;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 22px;
    }

    .care-tool-icon.blue { background: #e8f4ff; }
    .care-tool-icon.green { background: var(--teal-light); }
    .care-tool-icon.amber { background: #fff5e0; }
    .care-tool-icon.purple { background: #f3eeff; }

    .care-tool-name {
      font-family: var(--font-display);
      font-size: 14px;
      font-weight: 800;
      color: var(--charcoal);
      line-height: 1.3;
    }

    .care-tool-desc {
      font-size: 12.5px;
      color: var(--gray-500);
      line-height: 1.5;
      flex: 1;
    }

    .care-tool-cta {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      font-family: var(--font-display);
      font-size: 12px;
      font-weight: 700;
      color: var(--teal);
    }

    .care-tool-cta svg { width: 12px; height: 12px; }

    /* =============================================
       RECOMMENDED READS
    ============================================= */
    .recommended-reads {
      padding: 64px 0;
    }

    .reads-tabs {
      display: flex;
      gap: 4px;
      margin-bottom: 32px;
      border-bottom: 2px solid var(--gray-100);
      overflow-x: auto;
      scrollbar-width: none;
    }

    .reads-tabs::-webkit-scrollbar { display: none; }

    .reads-tab {
      padding: 10px 18px;
      font-family: var(--font-display);
      font-size: 13px;
      font-weight: 700;
      color: var(--gray-500);
      border-radius: var(--radius-sm) var(--radius-sm) 0 0;
      white-space: nowrap;
      transition: color 0.15s, background 0.15s;
      position: relative;
      bottom: -2px;
      border-bottom: 2px solid transparent;
    }

    .reads-tab:hover { color: var(--teal); }

    .reads-tab.active {
      color: var(--teal);
      border-bottom-color: var(--teal);
    }

    .reads-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    .read-card {
      background: var(--white);
      border: 1px solid var(--gray-100);
      border-radius: var(--radius-md);
      overflow: hidden;
      transition: box-shadow 0.2s, transform 0.15s;
      cursor: pointer;
      display: flex;
      flex-direction: column;
    }

    .read-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-3px);
    }

    .read-card-img {
      height: 180px;
      overflow: hidden;
      background: linear-gradient(135deg, var(--teal-light) 0%, var(--gray-100) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 52px;
      position: relative;
    }

    .read-card-img::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(to bottom, transparent 50%, rgba(0,0,0,0.05) 100%);
    }

    .read-card-body {
      padding: 18px;
      flex: 1;
      display: flex;
      flex-direction: column;
    }

    .read-card-category {
      font-size: 10px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.7px;
      color: var(--teal);
      margin-bottom: 8px;
    }

    .read-card-title {
      font-family: var(--font-display);
      font-size: 15px;
      font-weight: 700;
      color: var(--charcoal);
      line-height: 1.4;
      margin-bottom: 10px;
      flex: 1;
    }

    .read-card-meta {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 11.5px;
      color: var(--gray-400);
    }

    .read-card-meta-dot {
      width: 3px;
      height: 3px;
      border-radius: 50%;
      background: var(--gray-200);
    }

    .read-card-reviewed {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      font-size: 11px;
      color: var(--teal);
      font-weight: 600;
    }

    .read-card-reviewed svg { width: 11px; height: 11px; }

    /* =============================================
       TRUST PILLARS
    ============================================= */
    .trust-section {
      background: linear-gradient(135deg, var(--charcoal) 0%, #2d2829 100%);
      padding: 72px 0;
      position: relative;
      overflow: hidden;
    }

    .trust-section::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='80' height='80' viewBox='0 0 80 80' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none'%3E%3Ccircle cx='40' cy='40' r='1' fill='%23ffffff' fill-opacity='0.04'/%3E%3C/g%3E%3C/svg%3E") repeat;
    }

    .trust-header-center {
      text-align: center;
      margin-bottom: 48px;
    }

    .trust-eyebrow {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1.2px;
      color: var(--teal-mid);
      margin-bottom: 12px;
    }

    .trust-title {
      font-family: var(--font-display);
      font-size: clamp(24px, 3vw, 36px);
      font-weight: 800;
      color: var(--white);
      letter-spacing: -0.6px;
      line-height: 1.2;
    }

    .trust-pillars-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
      position: relative;
    }

    .trust-pillar {
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: var(--radius-md);
      padding: 28px 24px;
      transition: background 0.2s, border-color 0.2s, transform 0.15s;
    }

    .trust-pillar:hover {
      background: rgba(255,255,255,0.1);
      border-color: rgba(2,131,141,0.4);
      transform: translateY(-3px);
    }

    .trust-pillar-icon {
      width: 48px;
      height: 48px;
      border-radius: var(--radius-sm);
      background: rgba(2,131,141,0.25);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 16px;
      font-size: 24px;
    }

    .trust-pillar-title {
      font-family: var(--font-display);
      font-size: 16px;
      font-weight: 800;
      color: var(--white);
      margin-bottom: 10px;
      line-height: 1.3;
    }

    .trust-pillar-desc {
      font-size: 13.5px;
      color: rgba(255,255,255,0.6);
      line-height: 1.6;
    }

    /* =============================================
       FEATURED PROGRAMS
    ============================================= */
    .featured-programs {
      padding: 64px 0;
    }

    .programs-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 18px;
    }

    .program-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--gray-100);
      transition: box-shadow 0.2s, transform 0.15s;
      cursor: pointer;
      background: var(--white);
    }

    .program-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-3px);
    }

    .program-card-img {
      height: 160px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
      position: relative;
    }

    .program-card-img-1 { background: linear-gradient(135deg, #fce4e4, #f8bbd0); }
    .program-card-img-2 { background: linear-gradient(135deg, #e3f2fd, #bbdefb); }
    .program-card-img-3 { background: linear-gradient(135deg, #e8f5e9, #c8e6c9); }
    .program-card-img-4 { background: linear-gradient(135deg, #fff3e0, #ffe0b2); }

    .program-card-label {
      position: absolute;
      top: 10px;
      left: 10px;
      font-size: 10px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      padding: 3px 8px;
      background: rgba(255,255,255,0.9);
      border-radius: 100px;
      color: var(--charcoal-light);
    }

    .program-card-body {
      padding: 16px;
    }

    .program-card-title {
      font-family: var(--font-display);
      font-size: 14px;
      font-weight: 700;
      color: var(--charcoal);
      line-height: 1.4;
      margin-bottom: 8px;
    }

    .program-card-link {
      font-size: 12px;
      font-weight: 600;
      color: var(--teal);
      display: flex;
      align-items: center;
      gap: 4px;
    }

    .program-card-link svg { width: 11px; height: 11px; }

    /* =============================================
       LATEST VIDEOS
    ============================================= */
    .latest-videos {
      background: var(--off-white);
      padding: 64px 0;
      border-top: 1px solid var(--gray-100);
    }

    .videos-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 18px;
    }

    .video-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      background: var(--white);
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--gray-100);
      cursor: pointer;
      transition: box-shadow 0.2s, transform 0.15s;
    }

    .video-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .video-thumb {
      position: relative;
      height: 148px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .video-thumb-1 { background: linear-gradient(135deg, #e0f7e9, #b2dfdb); }
    .video-thumb-2 { background: linear-gradient(135deg, #fce4ec, #f8bbd0); }
    .video-thumb-3 { background: linear-gradient(135deg, #e3f2fd, #bbdefb); }
    .video-thumb-4 { background: linear-gradient(135deg, #fff8e1, #ffecb3); }

    .video-thumb-emoji { font-size: 40px; }

    .play-btn {
      position: absolute;
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: rgba(255,255,255,0.92);
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: 0 4px 16px rgba(0,0,0,0.2);
      transition: transform 0.15s, background 0.15s;
    }

    .video-card:hover .play-btn {
      transform: scale(1.08);
      background: var(--white);
    }

    .play-btn svg { width: 18px; height: 18px; color: var(--teal); margin-left: 2px; }

    .video-duration {
      position: absolute;
      bottom: 8px;
      right: 8px;
      background: rgba(0,0,0,0.7);
      color: white;
      font-size: 11px;
      font-weight: 600;
      padding: 2px 6px;
      border-radius: 4px;
    }

    .video-card-body {
      padding: 14px 16px;
    }

    .video-category {
      font-size: 10px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      color: var(--teal);
      margin-bottom: 6px;
    }

    .video-title {
      font-family: var(--font-display);
      font-size: 13.5px;
      font-weight: 700;
      color: var(--charcoal);
      line-height: 1.4;
    }

    /* =============================================
       FOOTER
    ============================================= */
    .site-footer {
      background: var(--charcoal);
      padding: 56px 0 0;
    }

    .footer-newsletter {
      background: rgba(2,131,141,0.15);
      border: 1px solid rgba(2,131,141,0.2);
      border-radius: var(--radius-lg);
      padding: 36px;
      margin-bottom: 48px;
      display: grid;
      grid-template-columns: 1fr 400px;
      gap: 40px;
      align-items: center;
    }

    .footer-newsletter-text {
      font-size: 15px;
      color: rgba(255,255,255,0.72);
      line-height: 1.6;
    }

    .footer-newsletter-title {
      font-family: var(--font-display);
      font-size: 20px;
      font-weight: 800;
      color: var(--white);
      margin-bottom: 8px;
    }

    .footer-form {
      display: flex;
      gap: 8px;
    }

    .footer-input {
      flex: 1;
      padding: 11px 16px;
      background: rgba(255,255,255,0.1);
      border: 1.5px solid rgba(255,255,255,0.2);
      border-radius: 100px;
      color: var(--white);
      font-size: 13px;
      outline: none;
      transition: border-color 0.15s;
    }

    .footer-input::placeholder { color: rgba(255,255,255,0.4); }
    .footer-input:focus { border-color: var(--teal); }

    .btn-footer-signup {
      padding: 11px 20px;
      background: var(--teal);
      color: var(--white);
      font-family: var(--font-display);
      font-size: 13px;
      font-weight: 700;
      border-radius: 100px;
      white-space: nowrap;
      transition: background 0.15s;
    }

    .btn-footer-signup:hover { background: var(--teal-dark); }

    .footer-main {
      display: grid;
      grid-template-columns: 240px 1fr;
      gap: 64px;
      padding-bottom: 40px;
    }

    .footer-brand .logo-text { color: var(--white); }
    .footer-brand .logo-text span { color: var(--teal-mid); }

    .footer-brand-desc {
      font-size: 13px;
      color: rgba(255,255,255,0.5);
      line-height: 1.6;
      margin-top: 12px;
    }

    .footer-social {
      display: flex;
      gap: 8px;
      margin-top: 20px;
    }

    .footer-social-link {
      width: 34px;
      height: 34px;
      border-radius: 50%;
      background: rgba(255,255,255,0.08);
      border: 1px solid rgba(255,255,255,0.12);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 14px;
      transition: background 0.15s, border-color 0.15s;
    }

    .footer-social-link:hover {
      background: rgba(2,131,141,0.3);
      border-color: var(--teal);
    }

    .footer-links-wrap {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
    }

    .footer-link {
      font-size: 13px;
      color: rgba(255,255,255,0.5);
      transition: color 0.15s;
      padding: 2px 4px;
    }

    .footer-link:hover { color: rgba(255,255,255,0.9); }

    .footer-link-dot {
      color: rgba(255,255,255,0.2);
      line-height: 1;
      margin: 0 2px;
    }

    .footer-legal {
      padding: 24px 0;
      border-top: 1px solid rgba(255,255,255,0.08);
    }

    .footer-legal p {
      font-size: 12px;
      color: rgba(255,255,255,0.3);
      line-height: 1.6;
    }

    /* =============================================
       RESPONSIVE
    ============================================= */
    @media (max-width: 1100px) {
      .hero-grid { grid-template-columns: 1fr 280px; gap: 28px; }
      .programs-grid { grid-template-columns: repeat(2, 1fr); }
      .videos-grid { grid-template-columns: repeat(2, 1fr); }
      .trust-pillars-grid { grid-template-columns: repeat(2, 1fr); }
      .tools-grid { grid-template-columns: 1fr; }
      .nutrition-hub-card { max-width: 100%; }
      .care-tools-grid { grid-template-columns: repeat(4, 1fr); }
      .topic-card { width: calc((100% - 60px) / 4); }
    }

    @media (max-width: 900px) {
      .hero-grid { grid-template-columns: 1fr; }
      .hero-visual { display: none; }
      .trending-articles { gap: 8px 0; }
      .trending-article { border-right: none; margin-right: 0; padding: 4px 0; width: 100%; }
      .trending-inner { flex-direction: column; gap: 12px; }
      .trending-label { border-right: none; padding-right: 0; margin-right: 0; }
      .footer-newsletter { grid-template-columns: 1fr; gap: 20px; }
      .footer-main { grid-template-columns: 1fr; gap: 32px; }
      .reads-grid { grid-template-columns: repeat(2, 1fr); }
      .care-tools-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 768px) {
      .nav-list, .header-actions { display: none; }
      .mobile-menu-btn { display: flex; margin-left: auto; }
      .site-logo { flex: 1; }
      .hero-title { font-size: 28px; }
      .section-title { font-size: 20px; }
      .trust-title { font-size: 22px; }
      .programs-grid { grid-template-columns: 1fr 1fr; }
      .videos-grid { grid-template-columns: 1fr 1fr; }
      .reads-grid { grid-template-columns: 1fr; }
      .topic-card { width: calc((100% - 40px) / 3); min-width: 110px; }
      .topic-img-wrap { width: 90px; height: 90px; font-size: 32px; }
      .newsletter-form { flex-direction: column; }
      .tools-section { padding: 40px 0; }
    }

    @media (max-width: 480px) {
      .container { padding: 0 16px; }
      .section-padding { padding: 44px 0; }
      .programs-grid, .videos-grid { grid-template-columns: 1fr; }
      .care-tools-grid { grid-template-columns: 1fr; }
      .trust-pillars-grid { grid-template-columns: 1fr; }
      .reads-grid { grid-template-columns: 1fr; }
      .hero-cta-group { flex-direction: column; align-items: flex-start; }
    }

    /* =============================================
       ANIMATIONS
    ============================================= */
    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(20px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .animate-in {
      animation: fadeInUp 0.5s ease-out both;
    }

    .animate-delay-1 { animation-delay: 0.1s; }
    .animate-delay-2 { animation-delay: 0.2s; }
    .animate-delay-3 { animation-delay: 0.3s; }
    .animate-delay-4 { animation-delay: 0.4s; }

    /* Scroll reveal */
    .reveal {
      opacity: 0;
      transform: translateY(24px);
      transition: opacity 0.55s ease-out, transform 0.55s ease-out;
    }

    .reveal.visible {
      opacity: 1;
      transform: translateY(0);
    }

    /* =============================================
       MISC
    ============================================= */
    .divider {
      height: 1px;
      background: var(--gray-100);
    }

    /* Tab content transitions */
    .reads-content { transition: opacity 0.2s; }
    .reads-content.fading { opacity: 0; }

    /* Mobile nav overlay */
    .mobile-nav-overlay {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.4);
      z-index: 900;
    }

    .mobile-nav-overlay.open { display: block; }

    .mobile-nav-panel {
      position: fixed;
      top: 0;
      right: -100%;
      bottom: 0;
      width: min(320px, 90vw);
      background: var(--white);
      z-index: 950;
      padding: 24px;
      overflow-y: auto;
      transition: right 0.3s ease-out;
      box-shadow: var(--shadow-lg);
    }

    .mobile-nav-panel.open { right: 0; }

    .mobile-nav-close {
      display: flex;
      justify-content: flex-end;
      margin-bottom: 20px;
    }

    .mobile-nav-close button {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: var(--gray-50);
      display: flex;
